local UIActionConstructNode = Class("UIActionConstructNode")
function UIActionConstructNode:__init()
    self._data = nil   --status progress taskId groupId
    self._cb = nil
end

function UIActionConstructNode:__delete()
    self._data = nil
    self._cb = nil
end

function UIActionConstructNode:Awake()
end

function UIActionConstructNode:Start()
    SetButtonAction(self.FontStyleButton, Bind(self, self.OnBtnJump))
    SetButtonAction(self.BtnReceive, Bind(self, self.OnBtnDraw))
end

function UIActionConstructNode:Refresh(data, isExpland, cb, isUp)
    if not data then
        return
    end
    self._data = data
    self._cb = cb
    self._isExpland = isExpland

    self:FillSelf()

    CfUtils.SetActive(self.Root.transform:Find("Refresh"), isUp)
end

function UIActionConstructNode:FillSelf()
    local vo = ActionUtils.GetRegionTaskVo(self._data.taskId)
    if not vo then
        return 
    end
    CfUtils.SetActive(self.ImgChain, self._data.ind > 1)
    local scr = CfUtils.GetLuaScr(self.CommonGoodsList, CommonGoodsListNode)
    if scr then
        local t = parse_rewards(vo.rewardId, vo.rewardNum)
        scr:FreshBaseUI(t, false)
    end
    CfUtils.FillText(self.NameTxt, vo.name)
    self.Slider.value = checkNumber(self._data.progress) / checkNumber(vo.taskContenNum)

    local t = ActionUtils.GetAllGroupTask(self._data.groupId)
    CfUtils.SetActive(self.ImgSuperposition, table.count(t) > 1 and not self._isExpland)

    local isUnlock = ActionUtils.IsUnlockTask(self._data.taskId) 
    local isDraw = ActionUtils.IsDrawTask(self._data.taskId) 
    local isCanDraw = ActionUtils.IsCanDrawTask(self._data.taskId) 

    if isDraw then
        self._data.progress = vo.taskContenNum
    end
    CfUtils.FillText(self.TitleText, localize("<size=30><color=#545454>_num1_</color></size>/_num2_", {_num1_ = self._data.progress, _num2_ = vo.taskContenNum}))

    local isCanJump = (checkNumber(vo.openType) > 0)
    CfUtils.SetActive(self.TextUnderway, not isCanDraw and not isDraw and isUnlock and not isCanJump)
    CfUtils.SetActive(self.FontStyleButton, not isCanDraw and not isDraw and isUnlock and isCanJump)
    CfUtils.SetActive(self.BtnReceive, isCanDraw and isUnlock)
    CfUtils.SetActive(self.HasReceived, isDraw)
    CfUtils.SetActive(self.Lock, not isUnlock)
end

function UIActionConstructNode:OnBtnDraw()
    local isUnlock = ActionUtils.IsUnlockTask(self._data.taskId) 
    if not isUnlock then
        GameUtils.Toast(localize("未解锁"))
        return
    end
    local isDraw = ActionUtils.IsDrawTask(self._data.taskId) 
    if isDraw then
        GameUtils.Toast(localize("已领取"))
        return
    end
    local isCanDraw = ActionUtils.IsCanDrawTask(self._data.taskId) 
    if not isCanDraw then
        GameUtils.Toast(localize("未达到领取奖励"))
        return
    end
    
    local vo = ActionUtils.GetRegionTaskVo(self._data.taskId)
    ActionComponent:OverseaRegionalMapTaskDrawReq(self._data.taskId, self._data.groupId, vo.regionBelong, function(rewards)
        if self._cb then
            self._cb(rewards)
        end
    end)
end

function UIActionConstructNode:OnBtnJump()
    local vo = ActionUtils.GetRegionTaskVo(self._data.taskId)
    if not vo then
        return 
    end
    cs_coroutine.start(function()
        local row = GoodsConfMgr:GetInstance():GetJumpModuleRow(vo.openType)
        local t = checkTable(CfUtils.Split(vo.openParameter))
        GoodsConfMgr:GetInstance():ExecuteJump(row, vo, nil, nil, t)
        RegionQuestMgr:GetInstance():ClearCurMapGo()
    end)
end

function UIActionConstructNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIActionConstructNode